DARK_VARS  = '  --bg-base:#0B1220; --bg-card:#111827; --bg-card2:#162032; --bg-input:#1C2B3A; --border:#1F2937; --border-lite:#2D3748; --primary:#6366F1; --primary-dark:#4F46E5; --primary-glow:rgba(99,102,241,0.25); --success:#10B981; --warning:#F59E0B; --danger:#EF4444; --cyan:#06B6D4; --purple:#A855F7; --text:#E5E7EB; --text-muted:#9CA3AF; --text-dim:#6B7280; --shadow-sm:0 2px 8px rgba(0,0,0,.45); --shadow-md:0 8px 24px rgba(0,0,0,.55); --sidebar-bg:#080E1A;'

LIGHT_VARS = '  --bg-base:#F8FAFC; --bg-card:#FFFFFF; --bg-card2:#F1F5F9; --bg-input:#FFFFFF; --border:#E5E7EB; --border-lite:#D1D5DB; --primary:#6366F1; --primary-dark:#4F46E5; --primary-glow:rgba(99,102,241,0.15); --success:#059669; --warning:#D97706; --danger:#DC2626; --cyan:#0891B2; --purple:#9333EA; --text:#111827; --text-muted:#6B7280; --text-dim:#9CA3AF; --shadow-sm:0 2px 8px rgba(0,0,0,.07); --shadow-md:0 8px 24px rgba(0,0,0,.12); --sidebar-bg:#F1F5F9;'

BASE_CSS   = "@import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700&display=swap'); :root{--radius-sm:8px;--radius-md:12px;--radius-lg:16px;--transition:all .18s ease;} html,body,[class*='css']{font-family:'Inter',system-ui,sans-serif!important;background:var(--bg-base)!important;color:var(--text)!important;} #MainMenu,footer,header{visibility:hidden;} .stDeployButton{display:none;} section[data-testid='stSidebar']>div:first-child{padding-top:0!important;} .block-container{padding:1.5rem 2rem 3rem!important;max-width:100%!important;} section[data-testid='stSidebar']{background:var(--sidebar-bg)!important;border-right:1px solid var(--border)!important;} section[data-testid='stSidebar'] *{color:var(--text)!important;} .sb-brand{display:flex;align-items:center;gap:10px;padding:20px 16px 16px;border-bottom:1px solid var(--border);margin-bottom:4px;} .sb-brand-icon{width:34px;height:34px;border-radius:8px;background:linear-gradient(135deg,#6366F1,#A855F7);display:flex;align-items:center;justify-content:center;font-size:18px;flex-shrink:0;} .sb-brand-name{font-size:15px;font-weight:700;} .sb-brand-sub{font-size:11px;color:var(--text-muted)!important;line-height:1.2;} .sb-section-label{font-size:10px;font-weight:700;letter-spacing:1.2px;color:var(--text-dim)!important;text-transform:uppercase;padding:14px 16px 6px;} section[data-testid='stSidebar'] .stButton>button{background:var(--bg-card2)!important;border:1px solid var(--border-lite)!important;color:var(--text-muted)!important;border-radius:var(--radius-sm)!important;font-size:12px!important;padding:6px 10px!important;transition:var(--transition)!important;text-align:left!important;width:100%!important;} section[data-testid='stSidebar'] .stButton>button:hover{background:rgba(99,102,241,.14)!important;border-color:var(--primary)!important;color:var(--text)!important;} section[data-testid='stSidebar'] label{font-size:11px!important;font-weight:600!important;color:var(--text-muted)!important;text-transform:uppercase!important;letter-spacing:.5px!important;} .page-titlebar{display:flex;align-items:center;justify-content:space-between;padding:0 0 20px;border-bottom:1px solid var(--border);margin-bottom:24px;} .page-title{font-size:22px;font-weight:700;color:var(--text);} .page-subtitle{font-size:13px;color:var(--text-muted);margin-top:2px;} .page-badges{display:flex;align-items:center;gap:8px;} .page-badge{background:rgba(99,102,241,.15);border:1px solid rgba(99,102,241,.35);color:var(--primary);border-radius:20px;padding:4px 12px;font-size:11px;font-weight:600;} .query-bar-wrapper{background:var(--bg-card);border:1px solid var(--border-lite);border-radius:var(--radius-lg);padding:16px 20px;margin-bottom:24px;box-shadow:var(--shadow-sm);} .query-bar-label{font-size:11px;font-weight:700;letter-spacing:.8px;color:var(--text-dim);text-transform:uppercase;margin-bottom:8px;} .stTextInput input{background:var(--bg-input)!important;border:1px solid var(--border-lite)!important;border-radius:var(--radius-sm)!important;color:var(--text)!important;font-size:14px!important;height:42px!important;padding:0 16px!important;transition:var(--transition)!important;} .stTextInput input:focus{border-color:var(--primary)!important;box-shadow:0 0 0 3px var(--primary-glow)!important;} .stTextInput input::placeholder{color:var(--text-dim)!important;} .stButton>button[kind='primary']{background:linear-gradient(135deg,#6366F1,#8B5CF6)!important;border:none!important;border-radius:12px!important;color:#fff!important;font-size:14px!important;font-weight:600!important;height:42px!important;min-height:42px!important;padding:0 22px!important;box-shadow:0 4px 14px rgba(99,102,241,.3)!important;transition:var(--transition)!important;} .stButton>button[kind='primary']:hover{box-shadow:0 6px 18px rgba(99,102,241,.45)!important;transform:translateY(-1px)!important;} .stButton>button[kind='secondary'],.stButton>button:not([kind]){background:var(--bg-card2)!important;border:1px solid var(--border-lite)!important;color:var(--text-muted)!important;border-radius:10px!important;font-size:13px!important;height:42px!important;min-height:42px!important;min-width:42px!important;display:flex!important;align-items:center!important;justify-content:center!important;transition:var(--transition)!important;} .stButton>button:not([kind]):hover{border-color:var(--primary)!important;color:var(--text)!important;} div[data-testid='metric-container']{background:var(--bg-card)!important;border:1px solid var(--border)!important;border-radius:var(--radius-md)!important;padding:18px 20px!important;box-shadow:var(--shadow-sm)!important;transition:var(--transition)!important;} div[data-testid='metric-container']:hover{border-color:var(--border-lite)!important;box-shadow:var(--shadow-md)!important;transform:translateY(-2px)!important;} div[data-testid='metric-container'] [data-testid='stMetricLabel']{font-size:11px!important;font-weight:700!important;letter-spacing:.8px!important;text-transform:uppercase!important;color:var(--text-muted)!important;} div[data-testid='metric-container'] [data-testid='stMetricValue']{font-size:26px!important;font-weight:700!important;color:var(--text)!important;letter-spacing:-.5px!important;} .chart-card{background:var(--bg-card);border:1px solid var(--border);border-radius:var(--radius-lg);padding:20px 20px 8px;box-shadow:var(--shadow-sm);margin-bottom:20px;transition:var(--transition);} .chart-card:hover{box-shadow:var(--shadow-md);border-color:var(--border-lite);} .chart-card-header{display:flex;align-items:center;justify-content:space-between;margin-bottom:4px;} .chart-card-title{font-size:13px;font-weight:600;color:var(--text);} .chart-card-badge{font-size:10px;font-weight:600;letter-spacing:.5px;padding:3px 8px;border-radius:12px;background:rgba(99,102,241,.12);color:var(--primary);border:1px solid rgba(99,102,241,.2);} .insight-card{background:rgba(99,102,241,.06);border:1px solid rgba(99,102,241,.2);border-left:4px solid var(--primary);border-radius:var(--radius-md);padding:20px 24px;margin:20px 0;} .insight-title{font-size:11px;font-weight:700;letter-spacing:.8px;color:var(--primary);text-transform:uppercase;margin-bottom:10px;} .insight-body{font-size:13.5px;line-height:1.75;color:var(--text-muted);} .anomaly-card{background:rgba(245,158,11,.06);border:1px solid rgba(245,158,11,.25);border-left:4px solid var(--warning);border-radius:var(--radius-md);padding:16px 20px;margin:16px 0;} .anomaly-title{font-size:11px;font-weight:700;letter-spacing:.8px;color:var(--warning);text-transform:uppercase;margin-bottom:10px;} .anomaly-item{font-size:13px;line-height:1.8;color:var(--text-muted);padding:3px 0;} .followup-card{background:var(--bg-card);border:1px solid var(--border);border-radius:var(--radius-md);padding:16px 20px;margin:16px 0;} .followup-title{font-size:11px;font-weight:700;letter-spacing:.8px;color:var(--text-dim);text-transform:uppercase;margin-bottom:12px;} .drill-card{background:rgba(16,185,129,.07);border:1px solid rgba(16,185,129,.2);border-left:4px solid var(--success);border-radius:var(--radius-sm);padding:12px 16px;margin:12px 0;font-size:13px;color:var(--success);} .section-label{font-size:10px;font-weight:700;letter-spacing:1.2px;color:var(--text-dim);text-transform:uppercase;margin:24px 0 12px;padding-bottom:8px;border-bottom:1px solid var(--border);display:flex;align-items:center;gap:8px;} .sql-card{background:var(--bg-card2);border:1px solid var(--border);border-radius:var(--radius-md);overflow:hidden;} .sql-card-header{background:var(--bg-card2);padding:8px 14px;font-size:10px;font-weight:700;letter-spacing:.8px;color:var(--text-dim);text-transform:uppercase;border-bottom:1px solid var(--border);} .sql-card-body{font-family:'JetBrains Mono','Fira Code',monospace;font-size:12px;color:var(--text-muted);padding:14px 16px;white-space:pre-wrap;word-break:break-all;line-height:1.65;} .empty-state{display:flex;flex-direction:column;align-items:center;justify-content:center;padding:64px 24px;text-align:center;} .empty-icon{font-size:56px;margin-bottom:20px;filter:drop-shadow(0 0 24px rgba(99,102,241,.3));} .empty-title{font-size:20px;font-weight:700;color:var(--text);margin-bottom:8px;} .empty-sub{font-size:14px;color:var(--text-muted);max-width:420px;line-height:1.6;} .chip{display:inline-block;padding:5px 12px;border-radius:20px;font-size:12px;font-weight:500;background:var(--bg-card2);color:var(--text-muted);border:1px solid var(--border-lite);margin:4px;} .stTabs [data-baseweb='tab-list']{background:transparent!important;border-bottom:1px solid var(--border)!important;gap:0!important;} .stTabs [data-baseweb='tab']{background:transparent!important;color:var(--text-muted)!important;border-bottom:2px solid transparent!important;font-size:13px!important;font-weight:500!important;padding:10px 18px!important;transition:var(--transition)!important;} .stTabs [aria-selected='true']{color:var(--primary)!important;border-bottom-color:var(--primary)!important;} .stTabs [data-baseweb='tab-panel']{padding-top:20px!important;} .streamlit-expanderHeader{background:var(--bg-card2)!important;border:1px solid var(--border)!important;border-radius:var(--radius-sm)!important;color:var(--text-muted)!important;font-size:13px!important;} .streamlit-expanderContent{background:var(--bg-card)!important;border:1px solid var(--border)!important;border-top:none!important;border-radius:0 0 var(--radius-sm) var(--radius-sm)!important;} .stProgress>div>div>div>div{background:linear-gradient(90deg,#4F46E5,#6366F1)!important;border-radius:4px!important;} .stProgress>div>div{background:var(--border)!important;border-radius:4px!important;} hr{border-color:var(--border)!important;margin:20px 0!important;} .stSelectbox [data-baseweb='select']>div,.stMultiSelect [data-baseweb='select']>div{background:var(--bg-input)!important;border:1px solid var(--border-lite)!important;border-radius:var(--radius-sm)!important;color:var(--text)!important;} .stSuccess{background:rgba(16,185,129,.1)!important;border:1px solid rgba(16,185,129,.25)!important;border-radius:var(--radius-sm)!important;} .stError{background:rgba(239,68,68,.1)!important;border:1px solid rgba(239,68,68,.25)!important;border-radius:var(--radius-sm)!important;} .stWarning{background:rgba(245,158,11,.1)!important;border:1px solid rgba(245,158,11,.25)!important;border-radius:var(--radius-sm)!important;}"

def get_css(theme: str = "dark") -> str:
    v = DARK_VARS if theme == "dark" else LIGHT_VARS
    return f"<style>:root{{{v}}}{BASE_CSS}</style>"

# Backwards-compat alias used by old code
CSS = get_css("dark")
